DEFAULT_COPYRIGHT = "© 2026 Vastra Care. All rights reserved."


def remove_footer_admin_mentions(apps, schema_editor):
    SiteSetting = apps.get_model("care", "SiteSetting")
    NavLink = apps.get_model("care", "NavLink")

    NavLink.objects.filter(url__icontains="/admin").delete()

    for row in SiteSetting.objects.all():
        text = (row.copyright_text or "").strip()
        if not text:
            continue
        lower = text.lower()
        if "django admin" not in lower and "edit site content" not in lower:
            continue
        # Drop anything from "— Django admin" / "- Django admin" onward
        stripped = re.split(r"\s*[—\-]\s*Django\s*admin", text, maxsplit=1, flags=re.I)[0].strip()
        if not stripped or len(stripped) < 8:
            stripped = DEFAULT_COPYRIGHT
        row.copyright_text = stripped[:180]
        row.save(update_fields=["copyright_text"])


def noop(apps, schema_editor):
    pass


